const fs = require('fs');

const MOD = 1000000007;

const fact = new Array(8).fill(1);
for (let i = 1; i <= 7; i++) {
    fact[i] = (fact[i - 1] * i) % MOD;
}

const invFact = new Array(8).fill(1);
invFact[7] = modPow(fact[7], MOD - 2);
for (let i = 6; i >= 0; i--) {
    invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
}

function modPow(base, exp) {
    let res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

function nCr(n, r) {
    if (r < 0 || r > n) return 0;
    return (fact[n] * invFact[r] % MOD) * invFact[n - r] % MOD;
}

function solve() {
    const input = fs.readFileSync(0, 'utf-8').trim();
    if (!input) return;
    const m = parseInt(input, 10);

    const digits = String(m).split('').map(Number);
    const n = digits.length;

    // dp[pos][cnt][tight]
    // pos: 0 to n
    // cnt: 0 to n
    // tight: 0 or 1
    const dp = Array.from({ length: n + 1 }, () => 
        Array.from({ length: n + 1 }, () => [0, 0])
    );
    dp[0][0][1] = 1;

    for (let i = 0; i < n; i++) {
        for (let c = 0; c <= n; c++) {
            for (let t = 0; t <= 1; t++) {
                const val = dp[i][c][t];
                if (val === 0) continue;
                const maxDigit = t ? digits[i] : 9;
                for (let d = 0; d <= maxDigit; d++) {
                    const nt = (t && d === maxDigit) ? 1 : 0;
                    const nc = c + (d === 4 || d === 7 ? 1 : 0);
                    if (nc <= n) {
                        dp[i + 1][nc][nt] = (dp[i + 1][nc][nt] + val) % MOD;
                    }
                }
            }
        }
    }

    const totalCounts = new Array(n + 1).fill(0);
    for (let c = 0; c <= n; c++) {
        totalCounts[c] = (dp[n][c][0] + dp[n][c][1]) % MOD;
    }

    // Exclude 0
    totalCounts[0] = (totalCounts[0] - 1 + MOD) % MOD;

    let ans = 0;

    for (let k = 1; k <= n; k++) {
        if (totalCounts[k] === 0) continue;

        const counts = totalCounts.slice();
        counts[k] = (counts[k] - 1 + MOD) % MOD;

        // DP for choosing 6 numbers
        // state: dp[chosen][sum]
        const chooseDP = Array.from({ length: 7 }, () => new Array(7 * n + 1).fill(0));
        chooseDP[0][0] = 1;

        for (let l = 0; l <= n; l++) {
            if (counts[l] === 0) continue;
            const ways = new Array(7).fill(0);
            ways[0] = 1;
            for (let i = 1; i <= 6; i++) {
                // C(counts[l], i)
                if (i > counts[l]) break;
                // Since counts[l] can be large, compute C(c, i) using formula c*(c-1)*...*(c-i+1)/i!
                let num = 1;
                for (let j = 0; j < i; j++) {
                    num = (num * (counts[l] - j)) % MOD;
                }
                ways[i] = (num * invFact[i]) % MOD;
            }

            const newDP = Array.from({ length: 7 }, () => new Array(7 * n + 1).fill(0));
            for (let chosen = 0; chosen <= 6; chosen++) {
                for (let s = 0; s <= 6 * n; s++) {
                    const cur = chooseDP[chosen][s];
                    if (cur === 0) continue;
                    for (let take = 0; take <= 6 - chosen; take++) {
                        if (ways[take] === 0) continue;
                        const nChosen = chosen + take;
                        const nSum = s + take * l;
                        if (nSum <= 6 * n) {
                            newDP[nChosen][nSum] = (newDP[nChosen][nSum] + cur * ways[take]) % MOD;
                        }
                    }
                }
            }
            // Copy back
            for (let i = 0; i <= 6; i++) {
                for (let j = 0; j <= 6 * n; j++) {
                    chooseDP[i][j] = newDP[i][j];
                }
            }
        }

        let totalWays = 0;
        for (let s = 0; s < k; s++) {
            totalWays = (totalWays + chooseDP[6][s]) % MOD;
        }

        ans = (ans + totalCounts[k] * totalWays % MOD * fact[6]) % MOD;
    }

    console.log(ans);
}

solve();
